-- Generated by Ergasterion from a product declaration. Do not edit by hand.
{{ config(materialized='table') }}

with
quarantined as (
    select
        product_name,
        product_status,
        product_code,
        product_record_id,
        product_source_id,
        product_source_system,
        product_brand,
        product_category,
        product_list_price,
        product_currency,
        product_as_of_date,
        violation_00
    from {{ ref("ecommerce__product_interface__checked") }}
),
violations as (
    select
        'product_code_not_null' as rule_name,
        product_name,
        product_status,
        product_code,
        product_record_id,
        product_source_id,
        product_source_system,
        product_brand,
        product_category,
        product_list_price,
        product_currency,
        product_as_of_date
    from quarantined
    where violation_00
)

select
    rule_name,
    product_name,
    product_status,
    product_code,
    product_record_id,
    product_source_id,
    product_source_system,
    product_brand,
    product_category,
    product_list_price,
    product_currency,
    product_as_of_date
from violations
